local GuiActorWindow = GuiActorWindow

local waitingQueue = {}

---@type DressUtil
local DressUtil = T(Global, "DressUtil")

---设置皮肤信息到GuiActorWindow上
---@param actorName string eg: boy.actor
---@param skins table userInfo.skins or http data
function GuiActorWindow:SetActorInfo(actorName, skins, rotate)
    if self:GetActorName() == actorName then
        self:RemoveActor()
    end
    self:SetActor1(actorName, "idle", rotate or 0)
    for _, item in pairs(skins or {}) do
        if item.unload then
            self:UnloadBodyPart(item.master)
        elseif item.color then
            self:SetCustomColor(item.color)
        else
            if item.signature then
                self:ChangeBodyPartTexture(item.master, item.slave, item.signature, item.color or "")
            end
            if GuiActorWindow.UseBodyPartDyeColor and item.dyeColors ~= nil then
                self:UseBodyPartDyeColor(item.master, item.slave, item.dyeColors or "")
            else
                self:UseBodyPart(item.master, item.slave)
            end
        end
    end
end

---ui内存优化新增 标记GuiActorWindow是否等待web回调
function GuiActorWindow:enterWaitingQueue()
    waitingQueue[self] = true
end

function GuiActorWindow:inWaiting()
    return waitingQueue[self]
end

function GuiActorWindow:leaveWaitingQueue()
    waitingQueue[self] = nil
end

---根据玩家userId设置皮肤到GuiActorWindow上，自动请求Http，自动缓存
function GuiActorWindow:SetActorByUserId(userId, rotate, updateCache, callback)
    self:enterWaitingQueue()
    local player = PlayerManager:getPlayerByUserId(userId)
    if player and player.Player and self.RefreshBodyPartTexture then
        self:RefreshBodyPartTexture(player.Player)
    end
    local user = UserInfoCache:GetCache(userId)
    if user then
        local actorName = user.sex == 1 and "boy.actor" or "girl.actor"
        self:SetActorInfo(actorName, {}, rotate)
    else
        self:SetActorInfo("boy.actor", {}, rotate)
    end
    UserInfoCache:GetCacheByUserIds({ userId }, function()
        local cache = UserInfoCache:GetCache(userId) or {}
        if updateCache then
            cache.skins = nil
        end
        WebService.GetPlayerDecoration(userId, function(skins)
            if not self:inWaiting() then
                return
            end
            local actorName = cache.sex == 1 and "boy.actor" or "girl.actor"
            local newSkins = skins
            if not LogicSetting.Instance():getHideArmor() then
                newSkins = DressUtil:checkPlayerArmor(userId, skins)
            end
            self:SetActorInfo(actorName, newSkins, rotate)
            if callback then
                callback()
            end
        end)
    end)
end

