---设置触摸滑动控件，Touch转移
---@param window GUIWindow
function GuiActorWindow:SetTouchSlideWindow(window)
    if not window then
        return
    end
    window:removeAllEvents()
    window:registerEvent(GUIEvent.TouchDown, function(events)
        self:TouchDown(events.position)
    end)
    window:registerEvent(GUIEvent.TouchMove, function(events)
        self:TouchMove(events.position)
    end)
    window:registerEvent(GUIEvent.TouchUp, function(events)
        self:TouchUp(events.position)
    end)
end